/**
 * Build-time image manifest reader (server components only, §14).
 * The manifest is generated by scripts/optimize-images.mjs into public/_img/manifest.json.
 * It is read with fs inside try/catch and never imported as a module (pitfall 21).
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export type ImageEntry = {
  width?: number;
  height?: number;
  /** srcset strings; empty when the manifest has no entry */
  avif: string;
  webp: string;
  src: string;
};

type Manifest = Record<string, ImageEntry>;

let cache: Manifest | null = null;

function readManifest(): Manifest {
  if (cache) return cache;
  try {
    cache = JSON.parse(readFileSync(join(process.cwd(), 'public', '_img', 'manifest.json'), 'utf8')) as Manifest;
  } catch {
    cache = {};
  }
  return cache;
}

/** Image data for a file in public/images/. Falls back to the original file. */
export function getImage(name: string): ImageEntry {
  const entry = readManifest()[name];
  if (entry) return entry;
  return { avif: '', webp: '', src: `/images/${name}` };
}

/** Largest emitted width ≤ target, else the smallest, else the original (OQ-8). */
export function pickVariant(entry: ImageEntry, target: number, format: 'webp' | 'avif'): string {
  const set = (format === 'avif' ? entry.avif : entry.webp)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => {
      const [url, w] = s.split(/\s+/);
      return { url, w: parseInt(w ?? '0', 10) };
    })
    .sort((a, b) => a.w - b.w);
  if (set.length === 0) return entry.src;
  const fit = set.filter((v) => v.w <= target);
  return (fit.length ? fit[fit.length - 1] : set[0]).url;
}
